DELETE FROM `npc_text_locale` WHERE `ID` = 17906 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17906, 'zhTW', '在城門外有名叫做達銳斯的狼人德魯伊，他應該能幫上你的忙。$B$B去找一個全身覆滿皮毛的大傢伙，你一眼就能看出是他。', '在城門外有名叫做達銳斯的狼人德魯伊，他應該能幫上你的忙。$B$B去找一個全身覆滿皮毛的大傢伙，你一眼就能看出是他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17952 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17952, 'zhTW', '雖然看起來這件文物儲存得還蠻完整的，但是你感受不到它有任何特殊之處。', NULL, '這件文物看起來似乎完好無損，不過它被泥土和汙泥厚厚覆蓋，很難看清楚真正的狀態。它似乎沒有任何內在的魔法特性。', NULL, '這件文物經歷過無數風霜，明顯出現了嚴重的耗損痕跡。它昔日所擁有的力量，恐怕早已蕩然無存。', NULL, '這件物品上黏著幾片葉子和樹枝，顯示它可能曾被某種生物當作巢穴的一部分。除此之外沒有其他值得注意之處。', NULL, '這件物品上刻著幾道奇怪的花紋，也許是巨魔試圖解讀它的起源時所留下的。看來他們並未成功，因為這件物品仍然毫無反應。', NULL, '這件文物上刻著神秘的符文，不過目前看來似乎已經失去了力量。', NULL, '這件物品品質低劣，很可能只是眾多在黑市氾濫的仿冒文物之一。', NULL, '這件物品上可以看到幾處乾涸的血跡，可能是巨魔們為了奪取這件文物而爭鬥所留下的。不過這東西本身相當平凡，恐怕不值得這場爭鬥。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17961 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17961, 'zhTW', '你要找深山礦工與珠寶設計協會?就在大鍛爐的北面。', '你要找深山礦工與珠寶設計協會?就在大鍛爐的北面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17967 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17967, 'zhTW', '鐵匠和助手們在戰士區的護甲商及武器商附近。', '鐵匠和助手們在戰士區的護甲商及武器商附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17986 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17986, 'zhTW', '這是紅寡婦貝絲堤拉克的孩子。她生出的孩子會替他們死去的兄弟報仇。', NULL, '我們現在正身處貝絲堤拉克的繁殖巢穴中心。北方那些柱子之後，她的子嗣正等著我們。牠們會不惜一切代價保護她的幼體。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18024 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18024, 'zhTW', '我在此處是為了確保一切會及時完成。$B$B經歷了海嘯的藏寶海灣尚未恢復正常!$B$B我們最不需要的，就是受到成群狂暴食人妖、殭屍食人妖、大批的毒蛇或是發瘋獵豹的攻擊。', NULL, '我在這裡代表藏寶海灣，維護我們在這次遠征中的利益。$B$B萬一出了什麼差錯，藏寶海灣可就麻煩大了。$B$B我們至今還沒從大災變的衝擊中完全恢復過來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18025 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18025, 'zhTW', NULL, '任何生物都擁有生存下去的意志。', NULL, '戰爭是什麼？不就是為了維護生命而戰嗎？就像種子努力破土而出一樣，我們也是為了自己的存在而戰。', NULL, '哈囉！你還真是讓我越來越喜歡了，就像顆冒芽的種子一樣呢。', NULL, '我們能打贏這場戰爭嗎？只有時間，呃，「百里香」才知道答案。', NULL, '這裡熱得要命，是誰叫他們把溫度「蕪菁」（調高）成這樣的?', NULL, '我喜歡你！我們「雜草」配「茴香」，一定會是很「梨」想的一對。', NULL, '有人說我很老套（像玉米一樣），但我倒覺得自己挺有「鼠尾草」般的智慧。', NULL, '哦，又是你啊！你覺得我們能不能「芥末」（鼓起）足夠的力量呢？');
DELETE FROM `npc_text_locale` WHERE `ID` = 18037 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18037, 'zhTW', '那些食人妖突然出現，劈頭就要我們幫忙。', NULL, '我幾乎聽不懂這些食人妖在說什麼。', NULL, '為什麼這些食人妖不自己解決他們自己的問題呢？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18041 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18041, 'zhTW', NULL, '很高興你能來到這裡，$n。', NULL, '歡迎來到熔火之流，$N。', NULL, '前方的燃焰喚醒者可不是好惹的，進去後千萬小心。', NULL, '我擔心洞穴深處可能有一位迷路的德魯伊，$N。請多加留意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18042 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18042, 'zhTW', NULL, '很高興你能來到這裡，$n。', NULL, '歡迎來到熔火之流，$N。', NULL, '前方的燃焰喚醒者可不是好惹的，進去後千萬小心。', NULL, '前方有很多熱力噴口，$N。如果你陷入困境，儘管善用它們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18046 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18046, 'zhTW', '我可以教導烹飪的技藝。\n\n你想要學嗎?', '我可以教導烹飪的技藝。\n\n你想要學嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18086 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18086, 'zhTW', '在兵營二樓跟出納員倫德瑞談談。\n\n\n\n他會安排把你的貨物存放在塞拉摩島的金庫中。', '在兵營二樓跟出納員倫德瑞談談。\n\n他會安排把你的貨物存放在塞拉摩島的金庫中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18087 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18087, 'zhTW', '到弓箭場找傑森·法蘭。', '到弓箭場找傑森·法蘭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18088 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18088, 'zhTW', '你會在普勞德摩爾女士的塔上找到在踱步的賀瑞斯·歐德爾。', '你會在普勞德摩爾女士的塔上找到在踱步的賀瑞斯·歐德爾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18089 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18089, 'zhTW', '在兵營外找正在訓練假人處監督訓練的卡爾曼修士。', '在兵營外找正在訓練假人處監督訓練的卡爾曼修士。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
