INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18090, 'zhTW', '在軍營旁邊的練習場找艾倫·布萊特吧。\n\n\n\n他跟古斯塔夫·範沃森醫生負責訓練島上的治療者們。', '在軍營旁邊的練習場找艾倫·布萊特吧。\n\n他跟古斯塔夫·範沃森醫生負責訓練島上的治療者們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18091 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18091, 'zhTW', '我不確定。試著問問看在碼頭的卡莉雅·哈斯丁。我聽說她在軍情七處有認識的人。', '我不確定。試著問問看在碼頭的卡莉雅·哈斯丁。我聽說她在軍情七處有認識的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18092 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18092, 'zhTW', '薩滿...?\n\n\n\n塞拉摩旅店裡住著一位看起來有點粗獷的矮人姑娘;我想她是來拜訪一位老朋友的。\n\n\n\n她或許能幫上你的忙。', '從石頭中傳來雷鳴般的聲音...$B$B你好，指揮官。你從希利蘇斯給議會領主帶來了什麼訊息?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18093 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18093, 'zhTW', '呃...嗯...不要告訴她是我叫你去的，但是你可以在中央塔上找到一個穿紅袍的女人。\n\n\n\n她的名字是雷蒂雅·方特。千萬別提到我!', '呃...嗯...不要告訴她是我叫你去的，但是你可以在中央塔上找到一個穿紅袍的女人。\n\n她的名字是雷蒂雅·方特。千萬別提到我!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18094 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18094, 'zhTW', '向兵營二樓的伊文凱恩隊長回報。他會安排你要進行的訓練。', '向兵營二樓的伊文凱恩隊長回報。他會安排你要進行的訓練。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18095 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18095, 'zhTW', '鏈金師納瑞特和布蘭特·加斯布魯姆在這裡的一間小店鋪教導鏈金和草藥學。他們應該可以幫到你。', '鏈金師納瑞特和布蘭特·加斯布魯姆在這裡的一間小店鋪教導鏈金和草藥學。他們應該可以幫到你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18096 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18096, 'zhTW', '我知道來訪的烏利布希矮人之一是個考古學家。\n\n\n\n應該是那個叫費伊娜的太太。他們都是探險者之類的。去旅館可以找到他們。', '我知道來訪的烏利布希矮人之一是個考古學家。\n\n應該是那個叫費伊娜的太太。他們都是探險者之類的。去旅館可以找到他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18097 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18097, 'zhTW', '去鐵匠鋪那裡找瑪蕾·霍斯頓。', '去鐵匠鋪那裡找瑪蕾·霍斯頓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18098 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18098, 'zhTW', '克瑞格·諾瓦德在旅店的廚房做事。他可以幫你。', '克瑞格·諾瓦德在旅店的廚房做事。他可以幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
