INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18104, 'zhTW', '我很確定來訪的烏利布希矮人之一是個珠寶匠。\n\n\n\n我想是那對夫妻中的丈夫，因格。他們兩個人都是探險者之類的。去旅館可以找到他們。', '我很確定來訪的烏利布希矮人之一是個珠寶匠。\n\n我想是那對夫妻中的丈夫，因格。他們兩個人都是探險者之類的。去旅館可以找到他們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18105 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18105, 'zhTW', '到塞拉摩的旅店找譚威爾兄弟。他們當中會有人能幫你。', '到瑟拉摩的旅店找譚威爾兄弟。他們當中會有人能幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18106 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18106, 'zhTW', '去塞拉摩的鐵匠鋪外面找叫克利克的矮人。\n\n\n\n他是個酒鬼，而且愛亂用炸藥，但是他還算友善，而且對礦坑相當熟悉。', '去瑟拉摩的鐵匠鋪外面找叫克利克的矮人。\n\n他是個酒鬼，而且愛亂用炸藥，但是他還算友善，而且對礦坑相當熟悉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18107 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18107, 'zhTW', '你應該去找山夏·馬克凡斯，就在塞拉摩的馬廄外面。', '你應該去找山夏·馬克凡斯，在塞拉摩爾的馬廄外面。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18108 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18108, 'zhTW', '提摩西·沃森特在塞拉摩比較大間的建築物之一工作。你可以在二樓找到他，他幫得到你。', '提摩西·沃森特在塞拉摩比較大間的建築物之一工作。你可以在二樓找到他，他幫得到你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18124 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18124, 'zhTW', NULL, '不用擔心。赤紅鞭笞者在我這裡會很安全。但是在我們更深入瞭解牠的行為模式之前，牠恐怕得繼續待在火源之界這裡。', NULL, '真是個獨一無二的樣本！有這麼多的可能性！我必須更加投入研究當地的動植物生態。', NULL, '在我埋首研究的同時，就要靠你來教導鞭笞者認識這個世界的道理了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18143 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18143, 'zhTW', NULL, '你對於看守者有任何的問題都可以在戰場上得到答案。', NULL, '什麼是看守者？我們就是那精準無比、一擊必殺的斬擊。', NULL, '什麼是看守者？我們就是死亡降臨前，那飛旋刀刃所發出的嗡鳴聲。', NULL, '什麼是看守者？我們就是潛伏在陰影中的寂靜。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18160 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18160, 'zhTW', '歡迎您，法師。我應該提供你關於魔法世界更深的見解嗎?', '歡迎，法師。我應該提供你關於魔法世界更深的見解嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18162 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18162, 'zhTW', '我現在沒空說教，$c。去別的地方尋找你的知識。', '我現在沒空說教，$c。去別的地方尋找你的知識。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18163 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18163, 'zhTW', '聖光給我們足以獲得勝利的力量和魔法。', '聖光給我們足以獲得勝利的力量和魔法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18165 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18165, 'zhTW', NULL, '任何生物都擁有生存下去的意志。', NULL, '戰爭是什麼？不就是為了維護生命而戰嗎？就像種子努力破土而出一樣，我們也是為了自己的存在而戰。', NULL, '哈囉！植物可是我的專長。你想打聽當地的植物生態嗎？', NULL, '沒有什麼比盛開的花朵更令人振奮的了！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18166 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18166, 'zhTW', '很抱歉，$c。我以為你是個有骨氣的人。你走吧;我們的秘密不告訴不牢靠的人。', '很抱歉，$c。我以為你是個有骨氣的人。你走吧;我們的秘密不告訴不牢靠的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18168 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18168, 'zhTW', '我們沒什麼好談的，$c。或許你該去找別人，和你比較志趣相投的人。', '我們沒什麼好談的，$c。或許你該去找別人，和你比較志趣相投的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18169 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18169, 'zhTW', '你喜歡槍械還是弓箭?', '你喜歡槍械還是弓箭?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18170 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18170, 'zhTW', '我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', '我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18172 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18172, 'zhTW', '我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', '我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18174 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18174, 'zhTW', '$N，想要我怎樣幫你進行訓練?', '$n，想要我怎樣幫你進行訓練?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18175 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18175, 'zhTW', '如果你在尋求訓練，我幫不上忙。', '如果你在尋求訓練，我幫不上忙。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18176 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18176, 'zhTW', '看來你做了錯誤的選擇，$c。', '看來你做了錯誤的選擇，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18195 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18195, 'zhTW', '你來加入戰鬥的嗎，$c?', '你來加入戰鬥的嗎，$c?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18269 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18269, 'zhTW', '暗月馬戲團開了!$B$B只要一點費用，我就可以把你傳送到籌備區去。$B$B你想要去嗎?', '暗月馬戲團開了!$B$B只要一點費用，我就可以把你傳送到籌備區去。$B$B你想要去嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18280 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18280, 'zhTW', '我們的以太魔科技有著以前的人無法想像的能力，可以修改物品秘法本質。我們能把物品存進一處獨立次元...只要少許的費用。詳情請洽詢我的同事。$B$B或者，你有東西要讓我看看嗎?', '我們的以太魔科技有著以前的人無法想像的能力，可以修改物品秘法本質。我們能把物品存進一處獨立次元...只要少許的費用。詳情請洽詢我的同事。$B$B或者，你有東西要讓我看看嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18284 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18284, 'zhTW', '嘿，嘿!$B$B我想你一定可以把圈圈丟到慢吞吞的烏龜身上。$B$B怎麼樣?', '嘿，嘿!$B$B我想你一定可以把圈圈丟到慢吞吞的烏龜身上。$B$B怎麼樣?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18286 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18286, 'zhTW', '你先給我一個遊戲代幣，然後我給你十個圈圈。$B$B把圈圈丟到那邊的肚邊龜身上... 有看到牠背上的杆子嗎?。$B$B就算你丟中的圈圈不夠多、沒法一次獲勝，只要再試一次就好了!你的點數可以沿用到下場遊戲。', '你先給我一個遊戲代幣，然後我給你十個圈圈。$B$B把圈圈丟到那邊的肚邊龜身上... 有看到牠背上的杆子嗎?。$B$B就算你丟中的圈圈不夠多、沒法一次獲勝，只要再試一次就好了!你的點數可以沿用到下場遊戲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18288 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18288, 'zhTW', '要架設馬戲團的場地並進行維護，是件很艱難的工作...', '要架設馬戲團的場地並進行維護，是件很艱難的工作...', '我一動手臂就痛得要命。', '我一動手臂就痛得要命。', '這道傷口好像怎麼都好不了。', '這道傷口好像怎麼都好不了。', '這是我最後一次獨自架設大砲了...', '這是我最後一次獨自架設大砲了...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18289 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18289, 'zhTW', '我們有錘子、有豺狼人。$B$B只要你有代幣，就可以用錘子痛扁豺狼人。', '我們有錘子、有豺狼人。$B$B只要你有代幣，就可以用錘子痛扁豺狼人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18290 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18290, 'zhTW', '在找舊版的蒸汽坦克嗎?$B$B我們有新版的讓你玩呢。$B$B通常，你會需要花費兩個代幣才能使用坦克的遙控裝置。但是因為你在軍事上的貢獻，我們給了你只要花一個代幣的折扣。$B$B我們暗月馬戲團感謝你的服務。', '在找舊版的蒸汽坦克嗎?$B$B我們有新版的讓你玩呢。$B$B通常，你會需要花費兩個代幣才能使用坦克的遙控裝置。但是因為你在軍事上的貢獻，我們給了你只要花一個代幣的折扣。$B$B我們暗月馬戲團感謝你的服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18301 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18301, 'zhTW', '三位以太魔科技師在暴風城教堂廣場南邊的運河旁開了家店。\n\n\n\n那家店的名字叫「三陣風」。看到奇怪的機械跟紫色的燈就沒錯了...你不會找不到的。\n\n\n\n他們會提供你想要的服務。', '三位以太魔科技師在暴風城教堂廣場南邊的運河旁開了家店。\n\n那家店的名字叫「三陣風」。看到奇怪的機械跟紫色的燈就沒錯了...你不會找不到的。\n\n他們會提供你想要的服務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18317 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18317, 'zhTW', '已經沒有遊戲能讓你玩了。', '已經沒有遊戲能讓你玩了。', '你現在又想幹嘛?', '你現在又想幹嘛?', '讓開點，也讓其他人有機會玩玩。', '讓開點，也讓其他人有機會玩玩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18321 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18321, 'zhTW', '有什麼我能幫你的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18322 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18322, 'zhTW', '有什麼我能幫你的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18348 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18348, 'zhTW', '你要有暗月遊戲代幣才能玩。$B$B馬戲團的每個代幣商人都有賣。$B$B我會幫你標記在你的地圖上。', '你要有暗月遊戲代幣才能玩。$B$B馬戲團的每個代幣商人都有賣。$B$B我會幫你標記在你的地圖上。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18350 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18350, 'zhTW', '首先，你先給我一個遊戲代幣。然後，我會給你一把錘子。你會看到豺狼人從遊戲區的桶子裡冒出來。$B$B用錘子打中豺狼人，你就會獲得分數。$B$B要特別注意的是，桶子會出現三種目標:普通豺狼人、大豺狼人，還有寶寶。$B$B普通豺狼人能獲得一分，大豺狼人算三分。至於寶寶?打中寶寶會害你摔跤暈倒...所以千萬不要動手打寶寶!$B$B如果你時間內無法打到夠多的豺狼人，只要多花個代幣就好了!因為你累積的點數是可以沿用到下一場遊戲的。', '首先，你先給我一個遊戲代幣。然後，我會給你一把錘子。你會看到豺狼人從遊戲區的桶子裡冒出來。$B$B用錘子打中豺狼人，你就會獲得分數。$B$B要特別注意的是，桶子會出現三種目標:普通豺狼人、大豺狼人，還有寶寶。$B$B普通豺狼人能獲得一分，大豺狼人算三分。至於寶寶?打中寶寶會害你摔跤暈倒...所以千萬不要動手打寶寶!$B$B如果你時間內無法打到夠多的豺狼人，只要多花個代幣就好了!因為你累積的點數是可以沿用到下一場遊戲的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18352 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18352, 'zhTW', '首先，你先給我一個遊戲代幣，然後你就能控制一臺蒸汽坦克。$B$B你得在限定的時間內擊中戰場上的目標，每摧毀一個目標就能贏得一點積分。$B$B但要小心:戰場上同時也有著敵方的坦克跟飛艇，被它們擊中會使你的坦克受損。$B$B你的分數在結束後會帶到下一場遊戲中，所以就算被打爆了也不用擔心。', '首先，你先給我一個遊戲代幣，然後你就能控制一臺蒸汽坦克。$B$B你得在限定的時間內擊中戰場上的目標，每摧毀一個目標就能贏得一點積分。$B$B但要小心:戰場上同時也有著敵方的坦克跟飛艇，被它們擊中會使你的坦克受損。$B$B你的分數在結束後會帶到下一場遊戲中，所以就算被打爆了也不用擔心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18353 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18353, 'zhTW', '首先，你得給我一個遊戲代幣，我就給你一把氣彈步槍。$B$B然後，用它射擊亮起來的目標。$B$B如果你動作夠快，在目標亮起來之後立刻射中它，就能獲得額外的分數。$B$B如果你在時間結束前沒辦法達到指定的分數，或你離開了場地，也不用擔心。你的分數會保留到下一場遊戲計算。', '首先，你得給我一個遊戲代幣，我就給你一把氣彈步槍。$B$B然後，用它射擊亮起來的目標。$B$B如果你動作夠快，在目標亮起來之後立刻射中它，就能獲得額外的分數。$B$B如果你在時間結束前沒辦法達到指定的分數，或你離開了場地，也不用擔心。你的分數會保留到下一場遊戲計算。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18362 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18362, 'zhTW', '您好，$c，歡迎來到暗月馬戲團的籌備區。$B$B這裡的門會把你帶到暗月馬戲團的位置。$B$B但若您在前往之前有任何問題，我可以幫忙回答。', '您好，$c，歡迎來到暗月馬戲團的籌備區。$B$B這裡的門會把你帶到暗月馬戲團的位置。$B$B但若您在前往之前有任何問題，我可以幫忙回答。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18363 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18363, 'zhTW', '暗月馬戲團裡頭有很多令人驚歎的東西。我們有個占卜師，一場演唱會、一場釣魚比賽跟許多小遊戲。$B$B我們一直在持續用新花樣來擴張馬戲團的規模!$B$B有任何特別的東西是你想知道的嗎?', '暗月馬戲團裡頭有很多令人驚歎的東西。我們有個占卜師，一場演唱會、一場釣魚比賽跟許多小遊戲。$B$B我們一直在持續用新花樣來擴張馬戲團的規模!$B$B有任何特別的東西是你想知道的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18364 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18364, 'zhTW', '小型坦克，就我記憶所及，一直都是馬戲團裡面很搶手的遊戲。$B$B我們有兩個競技場來讓坦克進行戰鬥。$B$B一個競技場要你在有限時間內摧毀目標，並避免被敵方坦克擊破。你只需要一個代幣就可以玩了$B$B在另一個競技場裡面，你可以使用自己的坦克或迷你飛艇跟朋友對戰。', '小型坦克，就我記憶所及，一直都是馬戲團裡面很搶手的遊戲。$B$B我們有兩個競技場來讓坦克進行戰鬥。$B$B一個競技場要你在有限時間內摧毀目標，並避免被敵方坦克擊破。你只需要一個代幣就可以玩了$B$B在另一個競技場裡面，你可以使用自己的坦克或迷你飛艇跟朋友對戰。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18365 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18365, 'zhTW', '衝擊者5000型超級大炮是一種最先進的單人拋射裝置。$B$B能以近乎龍的飛行速度射出彈頭，這門大炮是布萊頓海默家族的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想要像只鳥一樣在空中翱翔，就去找瑪克希瑪·布萊頓海默。', '衝擊者5000型超級大炮是一種最先進的單人拋射裝置。$B$B能以近乎龍的飛行速度射出彈頭，這門大炮是布萊頓海默家族的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想要像只鳥一樣在空中翱翔，就去找瑪克希瑪·布萊頓海默。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18366 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18366, 'zhTW', '痛扁豺狼人是一個充滿樂趣的遊戲，讓你痛扁...豺狼人。$B$B這是個新玩意，我們很多人都很愛玩。好吧，其實賽吉並不是很喜歡這個遊戲。', '痛扁豺狼人是一個充滿樂趣的遊戲，讓你痛扁...豺狼人。$B$B這是個新玩意，我們很多人都很愛玩。好吧，其實賽吉並不是很喜歡這個遊戲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18369 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18369, 'zhTW', '我們想要確保來看馬戲團的觀眾，不管是任何年齡層，都會喜愛這些遊戲。$B$B丟圈圈是一個簡單的遊戲，你只要試著把圈圈丟到烏龜的背上就可以了。$B$B這是我最愛的遊戲之一。', '我們想要確保來看馬戲團的觀眾，不管是任何年齡層，都會喜愛這些遊戲。$B$B丟圈圈是一個簡單的遊戲，你只要試著把圈圈丟到烏龜的背上就可以了。$B$B這是我最愛的遊戲之一。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18370 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18370, 'zhTW', '瑞林負責經營打靶場。$B$B那裡只有三個打靶的目標，命中的速度越快、分數越高。$B$B這是我最喜歡的遊戲。', '瑞林負責經營打靶場。$B$B那裡只有三個打靶的目標，命中的速度越快、分數越高。$B$B這是我最喜歡的遊戲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18371 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18371, 'zhTW', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個豺狼人。不過他是一個非常特別的豺狼人，擁有占卜你未來的能力!', '我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個豺狼人。不過他是一個非常特別的豺狼人，擁有占卜你未來的能力!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18372 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18372, 'zhTW', '哈羅，$c，歡迎來到暗月馬戲團。$B$B這裡有很多東西可以玩，對於第一次來的參觀者可能會覺得不知從何下手。我就是因為這個原因來幫忙的。$B$B你有任何疑問嗎?', '哈羅，$c，歡迎來到暗月馬戲團。$B$B這裡有很多東西可以玩，對於第一次來的參觀者可能會覺得不知從何下手。我就是因為這個原因來幫忙的。$B$B你有任何疑問嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18390 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18390, 'zhTW', '把場地設定妥當還真的不簡單。', '把場地設定妥當還真的不簡單。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18429 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18429, 'zhTW', '很抱歉，但是如果我讓你牽走一匹馬，羅娜會很生氣的。\n\n牠們只能給吉爾尼斯的聲望達到崇拜的朋友!', '很抱歉，但是如果我讓你牽走一匹馬，羅娜會很生氣的。\n\n牠們只能給吉爾尼斯的聲望達到崇拜的朋友!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18430 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18430, 'zhTW', '羅娜說有一個真的很勇敢的冒險者救了她家族果園附近的馬。\n\n我向她請求照顧那些隨著我們渡海的馬匹。聖光保佑，我從父母那裡學會養馬的技藝!\n\n你有興趣買一匹上好的吉爾尼斯坐騎嗎?', '羅娜說有一個真的很勇敢的冒險者救了她家族果園附近的馬。\n\n我向她請求照顧那些隨著我們渡海的馬匹。聖光保佑，我從父母那裡學會養馬的技藝!\n\n你有興趣買一匹上好的吉爾尼斯坐騎嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18444 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18444, 'zhTW', '我們周遭每天都有驚奇神秘的事物，不僅僅是在暗月馬戲團這裡。我們整理了一份列表，是你可能平日就會碰上的驚奇事物。這本「暗月野地指南」能幫你尋找世界各地的驚奇事物。$B$B只要指南在手，你可能會碰上你前所未見的東西。有些過去你瞧不上眼的東西，說不定現在已經成為別人夢寐以求的寶物。$B$B帶著這本指南，睜大你的眼睛注意各種不尋常的東西。$B$B萬一你把指南搞丟了，來找我們，我們會免費再送你一本。', '我們周遭每天都有驚奇神秘的事物，不僅僅是在暗月馬戲團這裡。我們整理了一份列表，是你可能平日就會碰上的驚奇事物。這本「暗月野地指南」能幫你尋找世界各地的驚奇事物。$B$B只要指南在手，你可能會碰上你前所未見的東西。有些過去你瞧不上眼的東西，說不定現在已經成為別人夢寐以求的寶物。$B$B帶著這本指南，睜大你的眼睛注意各種不尋常的東西。$B$B萬一你把指南搞丟了，來找我們，我們會免費再送你一本。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18463 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18463, 'zhTW', '暗月馬戲團開了!$B$B只要一點費用，我就可以把你傳送到籌備區去。$B$B你想要去嗎?', '暗月馬戲團開了!$B$B只要一點費用，我就可以把你傳送到籌備區去。$B$B你想要去嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18559 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18559, 'zhTW', '我們在等導遊。', '我們在等導遊。', 'Tour guide taking forever...', 'Tour guide taking forever...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18560 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18560, 'zhTW', '我們等導遊來吧。', '我們等導遊來吧。', '希望導遊能快點到。', '希望導遊能快點到。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18562 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18562, 'zhTW', '你是來導遊的?', '你是來導遊的?', '你是我的導遊嗎?', '你是我的導遊嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18563 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18563, 'zhTW', '如果你不是來這裡當導遊的，那就走開。', '如果你不是來這裡當導遊的，那就走開。', '你是來帶團的，還是只是來瞪著我們看的?快滾。', '你是來帶團的，還是只是來瞪著我們看的?快滾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 18583 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (18583, 'zhTW', '你準備好了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
